          emit({ type: 'mutation', fault: fault.id, ...rec.mutation });

          baseFiles = fixedFiles;
          baseDir = fixedDir;
          baseTarget = fixedTarget;
          baseResults = v.results;
          rec.status = 'fixed';
          break;
        }

